// LICENSES.md, generated by `npm run licenses` (scripts/licenses.mjs), lists every package that may ship with its
// version and licence text. A Renovate bump of apexcharts, mermaid or @fontsource/montserrat, or lock-file maintenance,
// changes package.json or package-lock.json and not LICENSES.md, so these tests turn that pull request red until
// someone runs `npm run licenses` and commits the result.
import {test, expect, beforeAll} from 'vitest';
import {existsSync, readFileSync} from 'node:fs';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {collectLicenses, renderLicenses} from '../../scripts/licenses.mjs';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const json = file => JSON.parse(readFileSync(join(ROOT, file), 'utf8'));
const licensesFile = readFileSync(join(ROOT, 'LICENSES.md'), 'utf8');
const RUN = 'run npm run licenses and commit LICENSES.md';

// the table of LICENSES.md as {name, version, licenses}, read once; the header and separator rows are skipped
const listed = licensesFile
  .split('\n')
  .filter(line => line.startsWith('| ') && !line.startsWith('| Package '))
  .map(line => {
    const [name, version, licenses] = line.slice(2).split(' | ');
    return {name, version, licenses};
  });

// what the installed packages say now, read once
let installed;
beforeAll(async () => {
  installed = await collectLicenses();
}, 60_000);

test('LICENSES.md lists every production dependency at the version package-lock.json installs', () => {
  const {dependencies} = json('package.json');
  const {packages} = json('package-lock.json');
  const names = Object.keys(dependencies);
  expect(names).toEqual(expect.arrayContaining(['apexcharts', 'mermaid', '@fontsource/montserrat']));
  for (const name of names) {
    const version = packages[`node_modules/${name}`]?.version;
    expect(version, `${name} in package-lock.json`).toBeTruthy();
    expect(
      listed.some(row => row.name === name && row.version === version),
      `LICENSES.md has no row for ${name} ${version}: ${RUN}`,
    ).toBe(true);
  }
});

test('the packages in LICENSES.md are the installed ones, down to the last transitive one', () => {
  // Mermaid's dependencies (DOMPurify, d3, lodash-es …) change with the lock file without package.json moving. The
  // rows are compared first, so a failure names the packages and versions that moved
  const expected = installed.map(({name, version, licenses}) => ({name, version, licenses}));
  expect(listed, `the table is out of date: ${RUN}`).toEqual(expected);
});

test('LICENSES.md is exactly what npm run licenses writes, licence texts included', () => {
  expect(licensesFile === renderLicenses(installed), `LICENSES.md is out of date: ${RUN}`).toBe(true);
});

test('the bundled font is listed with the SIL Open Font Licence and its text', () => {
  // Montserrat's files ship in dist/fonts/ (spec 08); the package's LICENSE holds the OFL and the font's copyright
  const version = json('package-lock.json').packages['node_modules/@fontsource/montserrat'].version;
  expect(listed).toContainEqual({name: '@fontsource/montserrat', version, licenses: 'OFL-1.1'});
  const text = licensesFile.split(`\n## @fontsource/montserrat ${version}\n`)[1]?.split('\n## ')[0] ?? '';
  expect(text).toContain('Copyright 2011 The Montserrat Project Authors');
  expect(text).toContain('SIL OPEN FONT LICENSE Version 1.1');
});

test('no vendor directory: no library is committed as a file', () => {
  expect(existsSync(join(ROOT, 'vendor'))).toBe(false);
});

test('package-lock.json names no package outside the repository', () => {
  // An `npm install` run inside a container with a global tool tree above the repo once left a key such as
  // `../../../opt/node-tools/node_modules/x` (marked extraneous): a machine layout in a shipped file that npm ci
  // tolerates but anything walking `packages` trips over
  const {packages} = json('package-lock.json');
  for (const [key, entry] of Object.entries(packages)) {
    expect(
      key === '' || key.startsWith('node_modules/'),
      `package-lock.json has a package outside node_modules: ${key}`,
    ).toBe(true);
    expect(entry.extraneous, `package-lock.json marks ${key} extraneous`).toBeUndefined();
  }
});

// small made-up lock files and package trees (test/unit/fixtures/licenses) that collectLicenses({root}) reads
const fixture = name => join(ROOT, 'test/unit/fixtures/licenses', name);

test('the generator lists production packages only, with a scoped name cut at the right node_modules/', async () => {
  // the dev, the extraneous and the ../x entries have no directory in the fixture: reading one would throw
  const rows = await collectLicenses({root: fixture('tree')});
  expect(rows.map(({name, version, licenses, repository}) => ({name, version, licenses, repository}))).toEqual([
    {
      name: '@acme/widget',
      version: '2.1.0',
      licenses: '(MIT OR Apache-2.0)',
      repository: 'https://github.com/acme/widget',
    },
    {name: 'nested', version: '0.3.0', licenses: 'ISC', repository: ''},
    {name: 'plain', version: '1.0.0', licenses: 'MIT', repository: 'https://github.com/acme/plain'},
  ]);
  expect(rows[0].text).toBe('Widget licence text.');
  expect(rows[1].text).toBe('This package ships no licence file; its package.json declares ISC.');
});

test('a package with no licence field is MIT* when its licence file carries the MIT grant, else the run stops', async () => {
  const [row] = await collectLicenses({root: fixture('mit-text')});
  expect(row).toMatchObject({name: 'unmarked', licenses: 'MIT*'});
  await expect(collectLicenses({root: fixture('no-license')})).rejects.toThrow('mystery@1.0.0');
});
